+package mapfluent
+
+import (
+	"fmt"
+	"math"
+	"reflect"
+	"strconv"
+	"strings"
+)
+
+func lookup(node any, segs []segment) (any, bool) {
+	cur := node
+	for _, seg := range segs {
+		switch n := cur.(type) {
+		case map[string]any:
+			if seg.isIndex {
+				return nil, false
+			}
+			v, ok := n[seg.key]
+			if !ok {
+				return nil, false
+			}
+			cur = v
+		case Map:
+			if seg.isIndex {
+				return nil, false
+			}
+			v, ok := n[seg.key]
+			if !ok {
+				return nil, false
+			}
+			cur = v
+		case []any:
+			if !seg.isIndex || seg.append || seg.index < 0 || seg.index >= len(n) {
+				return nil, false
+			}
+			cur = n[seg.index]
+		default:
+			return nil, false
+		}
+	}
+	return cur, true
+}
+
+func toMapAnyOK(v any) (Map, bool) {
+	switch x := v.(type) {
+	case Map:
+		return x, true
+	case map[string]any:
+		return Map(x), true
+	default:
+		return nil, false
+	}
+}
+
+func toSliceAnyOK(v any) ([]any, bool) {
+	switch x := v.(type) {
+	case []any:
+		return x, true
+	case nil:
+		return nil, false
+	}
+	rv := reflect.ValueOf(v)
+	if rv.Kind() != reflect.Slice && rv.Kind() != reflect.Array {
+		return nil, false
+	}
+	out := make([]any, rv.Len())
+	for i := 0; i < rv.Len(); i++ {
+		out[i] = rv.Index(i).Interface()
+	}
+	return out, true
+}
+
+func toStringOK(v any) (string, bool) {
+	switch x := v.(type) {
+	case nil:
+		return "", false
+	case string:
+		return x, true
+	case []byte:
+		return string(x), true
+	case fmt.Stringer:
+		return x.String(), true
+	}
+	rv := reflect.ValueOf(v)
+	switch rv.Kind() {
+	case reflect.Bool:
+		return strconv.FormatBool(rv.Bool()), true
+	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
+		return strconv.FormatInt(rv.Int(), 10), true
+	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
+		return strconv.FormatUint(rv.Uint(), 10), true
