	if !ok {
		return arr, false
	}
	deleteInto(map[string]any(childMap), segs[1:])
	arr[idx] = map[string]any(childMap)
	return arr, true
}

func mergeInto(dst, src map[string]any) {
	for k, v := range src {
		if sv, ok := toMapAnyOK(v); ok {
			if dv, ok := toMapAnyOK(dst[k]); ok {
				mergeInto(map[string]any(dv), map[string]any(sv))
				dst[k] = map[string]any(dv)
				continue
			}
		}
		dst[k] = v
	}
}

func cloneValue(v any) any {
	switch x := v.(type) {
	case Map:
		out := make(map[string]any, len(x))
		for k, vv := range x {
			out[k] = cloneValue(vv)
		}
		return Map(out)
	case map[string]any:
		out := make(map[string]any, len(x))
		for k, vv := range x {
			out[k] = cloneValue(vv)
		}
		return out
	case []any:
		out := make([]any, len(x))
		for i, vv := range x {
			out[i] = cloneValue(vv)
		}
		return out
	default:
		return v
	}
}

